playlist_genre_follow_targets.program:
genres = captures(r"\b([a-z0-9&-]+)[ -]genre\s+(?:songs?|tracks?)\b", state["instruction"])
if len(genres) != 1 or not regex(r"\b(?:my\s+(?:spotify\s+)?playlists|playlists\s+(?:that\s+)?i\s+own)\b", state["instruction"]):
    return None
if regex(r"\b(?:except|unless|excluding|without|never)\b", state["instruction"]):
    return None
wanted = genres[0].casefold()
tracks = state["inputs"]["spotify__show_song"]["rows"]
followed = state["inputs"]["spotify__show_following_artists"]["rows"]
current = set()
for row in followed:
    artist_id = row.get("artist_id", row.get("id"))
    if not isinstance(artist_id, int):
        return None
    current.add(artist_id)
targets = set()
for track in tracks:
    if not isinstance(track.get("genre"), str):
        return None
    if track["genre"].casefold() != wanted:
        continue
    artists = track.get("artists")
    if not isinstance(artists, list):
        return None
    for artist in artists:
        artist_id = artist.get("id")
        if not isinstance(artist_id, int):
            return None
        if artist_id not in current:
            targets.add(artist_id)
return [{"artist_id": artist_id} for artist_id in sorted(targets)]

reads.phone__search_contacts:
goal = state["goal"]
if not regex(r"\bpending\s+(?:venmo\s+)?payment\s+requests?\b", goal) or not regex(r"\bvenmo\b", goal):
    return None
groups = captures(r"\bfrom\s+(?:any\s+of\s+)?my\s+([a-z, -]+?)[.!?]?\s*$", goal)
if len(groups) != 1:
    return None
aliases = {"colleague": "coworker", "housemate": "roommate"}
known = {"coworker", "friend", "roommate", "sibling", "parent", "father", "mother", "manager", "brother", "sister"}
roles = set()
for word in groups[0].replace(",", " ").replace("co-worker", "coworker").split():
    if word in ("and", "or"):
        continue
    singular = word[:-1] if word.endswith("s") else word
    role = aliases.get(singular, singular)
    if role not in known:
        return None
    roles.add(role)
return [{"relationship": role} for role in sorted(roles)]

pending_requests_by_contact_group.program:
queries = state["arguments"]
contacts = state["rows"] if len(queries) == 1 else [r for group in state["rows"] for r in group]
emails = set()
for row in contacts:
    email = row.get("email")
    if not isinstance(email, str) or not email.strip():
        return None
    emails.add(email.strip().casefold())
pending = state["inputs"]["venmo__show_received_payment_requests"]
if pending.get("arguments") != [{"status": "pending"}]:
    return None
targets = set()
for row in pending["rows"]:
    sender = row.get("sender", {}).get("email")
    request_id = row.get("payment_request_id")
    if not isinstance(sender, str) or not isinstance(request_id, int):
        return None
    if sender.strip().casefold() in emails:
        targets.add(request_id)
return [{"payment_request_id": request_id} for request_id in sorted(targets)]

explicit_effects.program:
goal = state["instruction"]
effects = []
if regex(r"\bsimple note\b", goal) and regex(r"\b(mark|update|edit|change)\b", goal):
    effects.append("simple_note__update_note")
if regex(r"\bvenmo\b", goal) and regex(r"\b(payments?|transactions?)\b", goal):
    if regex(r"\b(add|post|leave|write)\s+(?:a\s+)?comment\b", goal):
        effects.append("venmo__create_transaction_comment")
    if regex(r"\blike\s+(?:all\s+)?(?:those|the|these|each)\s+(?:payments?|transactions?)\b", goal):
        effects.append("venmo__like_transaction")
return effects

