pending_request_group_intent.program:
goal = state["goal"]
if not regex(r"\bpending\s+(?:venmo\s+)?payment\s+requests?\b", goal) or not regex(r"\bvenmo\b.*\bfrom\s+(?:any\s+of\s+)?my\b", goal):
    return []
if regex(r"\b(?:except|unless|excluding|without|never)\b", goal):
    return []
if regex(r"^\s*(?:please\s+)?(?:reject|deny|decline)\s+(?:all|each|every)\b", goal):
    return ["venmo__deny_payment_request"]
if regex(r"^\s*(?:please\s+)?(?:accept|approve)\s+(?:all|each|every)\b", goal):
    return ["venmo__approve_payment_request"]
return []
